<?php
declare(strict_types=1);
namespace App\Services;
use App\Repositories\{StudentRepository,FeeRepository};
use App\Support\UploadPolicy;
final class StudentService{
private const MAP=['studentname'=>'student_name','reg'=>'registration_no','doa'=>'date_of_admission','class'=>'class_id','student_fee'=>'monthly_fee_override','discount_type'=>'discount_type','discount'=>'discount_value','Gphone'=>'mobile','dob'=>'date_of_birth','gender'=>'gender','nationality'=>'nationality','idmark'=>'identification_mark','blood'=>'blood_group','desease'=>'disease','scnic'=>'birth_form_nic','cast'=>'caste','pr'=>'previous_school','previous_board'=>'previous_board','previousid'=>'previous_id_board_roll','board_registration_no'=>'board_registration_no','board_roll_no'=>'board_roll_no','additionalinfo'=>'additional_note','os'=>'orphan_student','osc'=>'osc','religion'=>'religion','family'=>'family','noc'=>'total_siblings','address'=>'address','guardian_name'=>'guardian_name','guardian_nic'=>'guardian_nic','guardian_mobile'=>'guardian_mobile','fname'=>'father_name','fedu'=>'father_education','fcnic'=>'father_nic','fmobile'=>'father_mobile','fo'=>'father_occupation','fp'=>'father_profession','fi'=>'father_income','mname'=>'mother_name','medu'=>'mother_education','mcnic'=>'mother_nic','mmobile'=>'mother_mobile','mo'=>'mother_occupation','mp'=>'mother_profession','mi'=>'mother_income'];
public function __construct(private readonly StudentRepository$r){}
public function data(array$input,int$institute,?string$picture=null):array{$d=['institute_id'=>$institute];foreach(self::MAP as$from=>$to){$v=$input[$from]??null;$d[$to]=is_string($v)?trim($v):$v;if($d[$to]==='')$d[$to]=null;}$d['student_name']=(string)($d['student_name']??'');$d['registration_no']=(string)($d['registration_no']??'');$d['date_of_admission']=(string)($d['date_of_admission']??'');$d['class_id']=(int)($d['class_id']??0);$d['monthly_fee_override']=$d['monthly_fee_override']===null?null:(float)$d['monthly_fee_override'];$d['discount_type']=in_array($d['discount_type']??'', ['percentage','fixed'],true)?$d['discount_type']:'percentage';$d['discount_value']=(float)($d['discount_value']??0);if($d['discount_type']==='percentage')$d['discount_value']=min(100,$d['discount_value']);$d['discount_in_fee']=$d['discount_type']==='percentage'?$d['discount_value']:0;if($picture!==null)$d['picture_path']=$picture;$d['updated_at']=date('Y-m-d H:i:s');return$d;}
public function storeImage(?array$file):string|false|null{if(!$file||($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;$p=new UploadPolicy(['image/jpeg','image/png'],['jpg','jpeg','png'],102400);if(!$p->validate($file))return false;$name=$p->safeFilename(pathinfo((string)$file['name'],PATHINFO_EXTENSION));$dir=BASE_PATH.'/public/uploads/students';if(!is_dir($dir))mkdir($dir,0775,true);if(!move_uploaded_file((string)$file['tmp_name'],$dir.'/'.$name))throw new \RuntimeException('Could not save student picture.');return'uploads/students/'.$name;}
public function storeDocument(?array$file,string$type):array|false|null{if(!$file||($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;$p=new UploadPolicy(['application/pdf','image/jpeg','image/png'],['pdf','jpg','jpeg','png'],5242880);if(!$p->validate($file))return false;$ext=strtolower(pathinfo((string)$file['name'],PATHINFO_EXTENSION));$name=$p->safeFilename($ext);$dir=BASE_PATH.'/public/uploads/student-documents';if(!is_dir($dir))mkdir($dir,0775,true);if(!move_uploaded_file((string)$file['tmp_name'],$dir.'/'.$name))throw new \RuntimeException('Could not save student document.');return['document_type'=>$type,'original_name'=>basename((string)$file['name']),'file_path'=>'uploads/student-documents/'.$name,'mime_type'=>(string)($file['type']??'application/octet-stream'),'file_size'=>(int)($file['size']??0)];}
public function create(array$d):int{$d['created_at']=$d['updated_at'];$pdo=$this->rDb();$pdo->beginTransaction();try{$id=$this->r->create($d);$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}$policy=$this->r->db()->query('SELECT admission_month_policy FROM fee_settings WHERE institute_id=:i',['i'=>$d['institute_id']])->fetchColumn()?:'current_month';$actor=(int)(user()['id']??0);if($policy==='current_month'&&$actor>0){try{$student=$this->r->find($id,(int)$d['institute_id']);if($student)(new FeeService(new FeeRepository($this->r->db()),$this->r))->ensureInvoice($student,(int)$d['institute_id'],date('Y-m'),$actor);}catch(\Throwable$billingError){error_log('Admission billing failed for student '.$id.': '.$billingError->getMessage());}}return$id;}
public function update(int$id,int$i,array$d):bool{unset($d['institute_id']);return$this->r->update($id,$i,$d);}
private function rDb():\PDO{return$this->r->db()->connection();}
}
